package android.graphics;
public class Canvas {public static final java.util.List<String> drawnTexts=new java.util.ArrayList<>();public static int pathDraws,lineDraws;public Canvas(Bitmap bitmap){}public int save(){return 0;}public void restore(){}public void scale(float x,float y){}public void drawRect(float l,float t,float r,float b,Paint p){}public void drawCircle(float x,float y,float radius,Paint p){}public void drawLine(float x0,float y0,float x1,float y1,Paint p){lineDraws++;}public void drawPath(Path path,Paint p){pathDraws++;}public void drawText(String text,float x,float y,Paint p){drawnTexts.add(text);}}
